buggy.gh66519_object_dtype_preservation:
import numpy as np
import pandas as pd
from pandas._libs import lib


def is_object(dtype):
    return 1.0 if dtype == object else 0.0


# (a) None before an out-of-int64 int, via maybe_convert_objects
try:
    res = lib.maybe_convert_objects(np.array([None, 2**63, -1], dtype=object))
    probe("null_before_2_63_object", is_object(res.dtype))
except OverflowError:
    probe("null_before_2_63_object", -1.0)

# (b) None before 2**64 - 1, via Series construction
try:
    s = pd.Series([None, 2**64 - 1, -1])
    probe("series_null_2_64_minus_1_object", is_object(s.dtype))
    try:
        probe("series_value_exact", 1.0 if int(s.iloc[1]) == 2**64 - 1 else 0.0)
    except (TypeError, ValueError):
        probe("series_value_exact", 0.0)
except OverflowError:
    probe("series_null_2_64_minus_1_object", -1.0)
    probe("series_value_exact", -1.0)

# (c) out-of-float64 int into Index / Series should stay object, no OverflowError
try:
    idx = pd.Index(np.array([10**400, 1], dtype=object))
    probe("index_above_float64_object", is_object(idx.dtype))
except OverflowError:
    probe("index_above_float64_object", -1.0)

try:
    s2 = pd.Series([10**400, 1])
    probe("series_above_float64_object", is_object(s2.dtype))
except OverflowError:
    probe("series_above_float64_object", -1.0)
